def test_render_template(assistant):
    class TestAssistant(Assistant):
        def render_template(self, *args, **kwargs):
            return'rendered'

    assistant.assistant = TestAssistant(assistant.app)
    assert render_template('test.html') =='rendered'
    assert _render_template('test.html') =='rendered'


