import pytest
from flask import Flask, render_template
from flask_assistant import Assistant, _render_template


def test_render_template_with_assistant(assistant):
    class TestAssistant(Assistant):
        def render_template(self, *args, **kwargs):
            return'rendered'

    assistant.assistant = TestAssistant(assistant.app)
    assert render_template('test.html') =='rendered'
    assert _render_template('test.html') =='rendered'


def test_render_template_without_assistant(assistant):
    with pytest.raises(RuntimeError):
        render_template('test.html')


