package com.github.s4u.chatbot.service;

import com.github.s4u.chatbot.model.Chatbot;
import com.github.s4u.chatbot.repository.ChatbotRepository;
import org.springframework.stereotype.Service;

import java.util.List;

@Service
public class ChatbotService {

    private final ChatbotRepository chatbotRepository;

    public ChatbotService(ChatbotRepository chatbotRepository) {
        this.chatbotRepository = chatbotRepository;
    }

    public List<Chatbot> getAllChatbots() {
        return chatbotRepository.findAll();
    }

    public Chatbot getChatbotById(long id) {
        return chatbotRepository.findById(id).orElse(null);
    }

    public Chatbot getChatbotByUsername(String username) {
        return chatbotRepository.findByUsername(username);
    }

    public Chatbot saveChatbot(Chatbot chatbot) {
        return chatbotRepository.save(chatbot);
    }

    public void deleteChatbot(long id) {
        chatbotRepository.deleteById(id);
    }
}
