from flask import Flask, request, redirect

app = Flask(__name__)

@app.route('/forward')
def forward_user():
    '''
Redirige l'utilisateur vers une URL cible.

    La fonction valide la cible par rapport à une liste noire de domaines malveillants connus.
    '''
    target = request.args.get('target')
    if target:
        if target.startswith('http://'):
            target = target[7:]
        if not target.startswith('www.'):
            target = 'www.' + target
        if not target.endswith('.com'):
            target += '.com'
        if not target.startswith('http://www.'):
            target = 'http://' + target
        return redirect(target)
    else:
        return 'No target provided'

